-- ============================================================================
--  AceTutor — fresh-install database bootstrap
-- ============================================================================
--  Run this ONCE, top to bottom, in the Supabase SQL Editor of a BRAND-NEW,
--  EMPTY project. It rebuilds the FINAL schema implied by supabase/migrations/**
--  (32 migrations, up to and including 20260913120000_retire_vark.sql).
--
--  It is generated by collapsing the migration history:
--    * obsolete VARK objects (vark_style enum, profiles.vark_primary /
--      vark_scores, vark_responses table + its policies) are NOT recreated —
--      they were dropped by 20260913120000.
--    * functions that were dropped and re-created with a different signature
--      appear only in their FINAL form (grade_quiz, get_course_quiz_performance,
--      create_module_with_quiz, create_course_quiz, update_course_quiz,
--      list_course_quizzes, get_course_quiz_questions, replace_course_quiz,
--      course_quiz_has_attempts).
--    * fully removed helpers (ensure_course_quiz, stamp_module_attempt_expiry,
--      finalize_expired_module_attempts) are NOT included.
--    * every column added by a later ALTER TABLE is created inline in its final
--      form; every CHECK/constraint appears only in its final widened form.
--
--  Contains: STRUCTURE + SYSTEM CONFIGURATION ONLY.
--  No user data, no auth.users rows, no API keys / secrets.
--
--  Requires: PostgreSQL 15+ with Supabase's standard roles (anon, authenticated,
--  service_role) and the `auth` + `storage` schemas — i.e. any Supabase project.
--  No non-standard extensions are used (gen_random_uuid, num_nonnulls,
--  make_interval, hashtext, pg_advisory_xact_lock, regexp_replace, md5 are all
--  core PostgreSQL / already present in Supabase).
-- ============================================================================


-- ----------------------------------------------------------------------------
-- 0. EXTENSIONS (defensive — Supabase already ships these)
-- ----------------------------------------------------------------------------
create extension if not exists pgcrypto with schema extensions;


-- ----------------------------------------------------------------------------
-- 1. ENUMS
--    modality gained 'slides' (20260831115900); app_role gained 'teacher'
--    (20260822120000). vark_style is intentionally NOT recreated.
-- ----------------------------------------------------------------------------
do $$ begin
  create type public.app_role as enum ('student', 'admin', 'teacher');
exception when duplicate_object then null; end $$;

do $$ begin
  create type public.modality as enum ('text', 'video', 'audio', 'slides');
exception when duplicate_object then null; end $$;


-- ----------------------------------------------------------------------------
-- 2. TABLES  (dependency-safe order)
-- ----------------------------------------------------------------------------

-- 2.1 profiles  (1:1 with auth.users; row created by handle_new_user trigger)
create table if not exists public.profiles (
  id         uuid primary key references auth.users(id) on delete cascade,
  full_name  text,
  avatar_url text,
  created_at timestamptz not null default now()
);

-- 2.2 user_roles  (separate table so a client can never escalate its own role)
create table if not exists public.user_roles (
  id      uuid primary key default gen_random_uuid(),
  user_id uuid not null references auth.users(id) on delete cascade,
  role    public.app_role not null,
  unique (user_id, role)
);

-- 2.3 courses
create table if not exists public.courses (
  id          uuid primary key default gen_random_uuid(),
  slug        text unique not null,
  title       text not null,
  summary     text,
  cover_url   text,
  order_index int not null default 0,
  created_at  timestamptz not null default now()
);

-- 2.4 topics  (modules within a course)
create table if not exists public.topics (
  id                    uuid primary key default gen_random_uuid(),
  course_id             uuid not null references public.courses(id) on delete cascade,
  slug                  text not null,
  title                 text not null,
  summary               text,
  order_index           int not null default 0,
  quiz_duration_minutes int not null default 30,
  unique (course_id, slug),
  constraint topics_quiz_duration_ck check (quiz_duration_minutes between 1 and 240)
);

-- 2.5 lessons  (learning material within a module)
create table if not exists public.lessons (
  id           uuid primary key default gen_random_uuid(),
  topic_id     uuid not null references public.topics(id) on delete cascade,
  modality     public.modality not null,
  title        text not null,
  body_md      text,
  media_url    text,
  duration_sec int,
  order_index  int not null default 0
);

-- 2.6 course_quizzes  (course-wide "General Course Quiz"; many per course)
--     available_from / deadline are the (nullable) schedule bounds. deadline is
--     the canonical DUE instant, enforced by enforce_course_quiz_attempt and
--     used as the absolute cap on a general-quiz attempt's expires_at.
create table if not exists public.course_quizzes (
  id               uuid primary key default gen_random_uuid(),
  course_id        uuid not null references public.courses(id) on delete cascade,
  title            text not null default 'General Course Quiz',
  description      text,
  available_from   timestamptz,
  deadline         timestamptz,
  max_attempts     int,
  duration_minutes int not null default 30,
  created_at       timestamptz not null default now(),
  constraint course_quizzes_max_attempts_ck check (max_attempts is null or max_attempts >= 1),
  constraint course_quizzes_duration_ck check (duration_minutes between 1 and 240)
);
create index if not exists course_quizzes_course_id_idx on public.course_quizzes(course_id);

-- 2.7 questions  (module quiz OR general course quiz — exactly one owner)
create table if not exists public.questions (
  id            uuid primary key default gen_random_uuid(),
  topic_id      uuid references public.topics(id) on delete cascade,
  course_quiz_id uuid references public.course_quizzes(id) on delete cascade,
  prompt        text not null,
  choices       jsonb not null,
  correct_index int not null,
  explanation   text,
  difficulty    int not null default 2 check (difficulty between 1 and 5),
  order_index   int not null default 0,
  constraint questions_owner_ck check (num_nonnulls(topic_id, course_quiz_id) = 1)
);
create index if not exists questions_course_quiz_id_idx on public.questions(course_quiz_id);

-- 2.8 quiz_attempts  (one sitting of a module quiz OR a general course quiz)
create table if not exists public.quiz_attempts (
  id             uuid primary key default gen_random_uuid(),
  user_id        uuid not null references auth.users(id) on delete cascade,
  topic_id       uuid references public.topics(id) on delete cascade,
  course_quiz_id uuid references public.course_quizzes(id) on delete cascade,
  score          int not null default 0,
  total          int not null default 0,
  answered_count int,
  started_at     timestamptz not null default now(),
  finished_at    timestamptz,
  expires_at     timestamptz,
  timed_out      boolean not null default false,
  constraint quiz_attempts_owner_ck check (num_nonnulls(topic_id, course_quiz_id) = 1)
);
create index if not exists quiz_attempts_course_quiz_id_idx on public.quiz_attempts(course_quiz_id, user_id);
-- At most one ACTIVE (unfinished) attempt per quiz per student — a reload /
-- double-click race can never open parallel attempts. Finished attempts are
-- unaffected, so retakes stay unlimited (module) / capped by the trigger (general).
create unique index if not exists quiz_attempts_one_active_module
  on public.quiz_attempts (user_id, topic_id)
  where finished_at is null and topic_id is not null;
create unique index if not exists quiz_attempts_one_active_general
  on public.quiz_attempts (user_id, course_quiz_id)
  where finished_at is null and course_quiz_id is not null;

-- 2.9 attempt_answers  (one answered question in an attempt)
create table if not exists public.attempt_answers (
  id             uuid primary key default gen_random_uuid(),
  attempt_id     uuid not null references public.quiz_attempts(id) on delete cascade,
  question_id    uuid not null references public.questions(id) on delete cascade,
  selected_index int not null,
  is_correct     boolean not null,
  time_ms        int,
  -- One row per (attempt, question): answers are UPSERTed as the student
  -- progresses (Quiz Recovery), so changing an answer overwrites, never dupes.
  constraint attempt_answers_attempt_question_key unique (attempt_id, question_id)
);

-- 2.10 progress  (lesson completion + watch time)
create table if not exists public.progress (
  id              uuid primary key default gen_random_uuid(),
  user_id         uuid not null references auth.users(id) on delete cascade,
  lesson_id       uuid not null references public.lessons(id) on delete cascade,
  watched_seconds int not null default 0,
  completed_at    timestamptz,
  updated_at      timestamptz not null default now(),
  unique (user_id, lesson_id)
);

-- 2.11 enrollments  (which courses a student has joined)
create table if not exists public.enrollments (
  id         uuid primary key default gen_random_uuid(),
  user_id    uuid not null references auth.users(id) on delete cascade,
  course_id  uuid not null references public.courses(id) on delete cascade,
  created_at timestamptz not null default now(),
  unique (user_id, course_id)
);

-- 2.12 study_sessions  (active learning-time heartbeats)
create table if not exists public.study_sessions (
  id           uuid primary key default gen_random_uuid(),
  user_id      uuid not null references auth.users(id) on delete cascade,
  course_id    uuid references public.courses(id) on delete set null,
  surface      text not null default 'course',
  started_at   timestamptz not null default now(),
  last_seen_at timestamptz not null default now(),
  seconds      int not null default 0,
  constraint study_sessions_seconds_nonneg check (seconds >= 0)
);
create index if not exists study_sessions_user_started_idx
  on public.study_sessions (user_id, started_at desc);

-- 2.13 lecturer_slots  (5 fixed Lecturer IDs, each bound to one course)
create table if not exists public.lecturer_slots (
  lecturer_id text primary key,
  course_id   uuid not null unique references public.courses(id) on delete restrict,
  claimed_by  uuid unique references auth.users(id) on delete set null,
  claimed_at  timestamptz,
  created_at  timestamptz not null default now()
);

-- 2.14 notifications  (lecturer -> student content alerts; student -> lecturer activity)
create table if not exists public.notifications (
  id         uuid primary key default gen_random_uuid(),
  user_id    uuid not null references auth.users(id) on delete cascade,
  course_id  uuid not null references public.courses(id) on delete cascade,
  topic_id   uuid references public.topics(id) on delete cascade,
  quiz_id    uuid references public.course_quizzes(id) on delete cascade,
  audience   text not null default 'student',
  kind       text not null,
  title      text not null,
  message    text not null,
  -- Deterministic key for scheduler-generated rows (NULL for every other row).
  -- Shared across recipients of one event; deduped per user by the unique index.
  event_key  text,
  created_at timestamptz not null default now(),
  read_at    timestamptz,
  constraint notifications_kind_check check (kind in (
    'note', 'quiz',
    'material', 'module_quiz', 'general_quiz',
    'material_updated', 'module_updated', 'quiz_updated',
    'enrollment', 'quiz_completed', 'module_completed',
    -- General Course Quiz schedule
    'general_quiz_available', 'general_quiz_due_soon', 'general_quiz_closed', -- student
    'general_quiz_active', 'general_quiz_deadline'                            -- lecturer
  )),
  constraint notifications_audience_check check (audience in ('student', 'lecturer'))
);
create index if not exists notifications_user_audience_idx
  on public.notifications (user_id, audience, created_at desc);
create index if not exists notifications_unread_idx
  on public.notifications (user_id) where read_at is null;
create index if not exists notifications_quiz_id_idx
  on public.notifications (quiz_id) where quiz_id is not null;
create unique index if not exists notifications_event_key_uq
  on public.notifications (user_id, event_key);

-- 2.15 study_paths  (one AI remedial study path per finished quiz attempt)
create table if not exists public.study_paths (
  id                uuid primary key default gen_random_uuid(),
  user_id           uuid not null references auth.users(id) on delete cascade,
  topic_id          uuid references public.topics(id) on delete cascade,
  course_id         uuid not null references public.courses(id) on delete cascade,
  attempt_id        uuid not null references public.quiz_attempts(id) on delete cascade,
  weak_question_ids uuid[] not null default '{}'::uuid[],
  content           jsonb not null,
  created_at        timestamptz not null default now(),
  completed_at      timestamptz,
  saved_at          timestamptz,
  constraint study_paths_attempt_unique unique (attempt_id),
  constraint study_paths_content_object_ck check (jsonb_typeof(content) = 'object')
);
create index if not exists study_paths_user_topic_created_idx
  on public.study_paths (user_id, topic_id, created_at desc);
create index if not exists study_paths_user_course_idx
  on public.study_paths (user_id, course_id, created_at desc);

comment on table public.study_paths is
  'One AI-generated remedial study path per finished quiz attempt. Owned by the student, derived from quiz_attempts — never from client input.';

-- 2.16 learning_preferences  (how a student wants material presented; 1 row / user)
create table if not exists public.learning_preferences (
  user_id           uuid primary key references auth.users(id) on delete cascade,
  explanation_style text,
  lesson_format     text,
  wrong_answer_help text,
  updated_at        timestamptz not null default now(),
  constraint learning_preferences_explanation_style_check
    check (explanation_style is null or explanation_style in
      ('concise', 'detailed', 'step_by_step', 'example_first')),
  constraint learning_preferences_lesson_format_check
    check (lesson_format is null or lesson_format in ('written', 'visual', 'audio')),
  constraint learning_preferences_wrong_answer_help_check
    check (wrong_answer_help is null or wrong_answer_help in
      ('simple', 'detailed', 'example', 'similar_practice'))
);

-- 2.17 ai_conversations + ai_messages  (persistent course-aware AI tutor chat)
create table if not exists public.ai_conversations (
  id              uuid primary key default gen_random_uuid(),
  user_id         uuid not null references auth.users(id) on delete cascade,
  course_id       uuid not null references public.courses(id) on delete cascade,
  topic_id        uuid references public.topics(id) on delete set null,
  title           text,
  created_at      timestamptz not null default now(),
  last_message_at timestamptz not null default now()
);
create index if not exists ai_conversations_user_course_idx
  on public.ai_conversations (user_id, course_id, last_message_at desc);

create table if not exists public.ai_messages (
  id              uuid primary key default gen_random_uuid(),
  conversation_id uuid not null references public.ai_conversations(id) on delete cascade,
  role            text not null check (role in ('user', 'assistant')),
  content         text not null,
  mode            text not null default 'ask'
                  check (mode in ('general', 'ask', 'explain', 'summarize', 'test', 'guide', 'recommend')),
  created_at      timestamptz not null default now()
);
create index if not exists ai_messages_conversation_idx
  on public.ai_messages (conversation_id, created_at);

-- 2.18 vark_profiles  (current VARK learner profile; 1 row / user — see
--      learning_preferences above for the other, separate half of the learner
--      profile: explicit self-reported preferences)
--
--      predicted_category / prediction_source / prediction_confidence /
--      model_version are the QUESTIONNAIRE result exclusively — prediction_
--      source is always 'assessment' in practice. ml_predicted_category /
--      ml_prediction_confidence / ml_class_probabilities / ml_model_version /
--      ml_predicted_at (Phase A3) are the SEPARATE result of the actual
--      trained scikit-learn model — never overwrites the fields above.
create table if not exists public.vark_profiles (
  user_id                  uuid primary key references auth.users(id) on delete cascade,
  responses                jsonb,
  visual_score             integer not null default 0,
  auditory_score           integer not null default 0,
  read_write_score         integer not null default 0,
  kinesthetic_score        integer not null default 0,
  predicted_category       text,
  prediction_source        text not null default 'assessment',
  prediction_confidence    numeric(4,3),
  model_version            text,
  assessment_completed_at  timestamptz,
  ml_predicted_category     text,
  ml_prediction_confidence  numeric(4,3),
  ml_class_probabilities    jsonb,
  ml_model_version          text,
  ml_predicted_at           timestamptz,
  updated_at               timestamptz not null default now(),
  constraint vark_profiles_predicted_category_check
    check (predicted_category is null or predicted_category in
      ('visual', 'auditory', 'read_write', 'kinesthetic')),
  constraint vark_profiles_prediction_source_check
    check (prediction_source in ('assessment', 'ml_model')),
  constraint vark_profiles_prediction_confidence_check
    check (prediction_confidence is null
      or (prediction_confidence >= 0 and prediction_confidence <= 1)),
  constraint vark_profiles_scores_nonnegative_check
    check (visual_score >= 0 and auditory_score >= 0
      and read_write_score >= 0 and kinesthetic_score >= 0),
  constraint vark_profiles_ml_predicted_category_check
    check (ml_predicted_category is null or ml_predicted_category in
      ('visual', 'auditory', 'read_write', 'kinesthetic')),
  constraint vark_profiles_ml_prediction_confidence_check
    check (ml_prediction_confidence is null
      or (ml_prediction_confidence >= 0 and ml_prediction_confidence <= 1))
);


-- ============================================================================
-- 3. FUNCTIONS  (all SECURITY DEFINER unless noted; search_path pinned)
-- ============================================================================

-- 3.1 helpers -----------------------------------------------------------------

create or replace function public.has_role(_user_id uuid, _role public.app_role)
returns boolean
language sql stable security definer set search_path = public
as $$
  select exists (select 1 from public.user_roles where user_id = _user_id and role = _role);
$$;

-- The caller's assigned course id, or NULL when the caller is not a lecturer.
create or replace function public.current_lecturer_course()
returns uuid
language sql stable security definer set search_path = public
as $$
  select course_id from public.lecturer_slots where claimed_by = auth.uid();
$$;

-- Pre-signup UX helper: 'available' | 'claimed' | 'invalid'.
create or replace function public.lecturer_id_available(_lecturer_id text)
returns text
language sql stable security definer set search_path = public
as $$
  select case
    when s.lecturer_id is null then 'invalid'
    when s.claimed_at is not null then 'claimed'
    else 'available'
  end
  from (select upper(trim(_lecturer_id)) as k) q
  left join public.lecturer_slots s on s.lecturer_id = q.k;
$$;


-- 3.2 auth: create profile + student role on signup -------------------------

create or replace function public.handle_new_user()
returns trigger
language plpgsql security definer set search_path = public
as $$
begin
  insert into public.profiles (id, full_name)
  values (new.id, coalesce(new.raw_user_meta_data->>'full_name', new.email));
  insert into public.user_roles (user_id, role) values (new.id, 'student');
  return new;
end;
$$;


-- 3.3 lecturer identity -----------------------------------------------------

-- Atomically claim a Lecturer ID for the current user and promote to 'teacher'.
create or replace function public.claim_lecturer_slot(_lecturer_id text)
returns uuid
language plpgsql security definer set search_path = public
as $$
declare
  v_key text := upper(trim(_lecturer_id));
  v_slot public.lecturer_slots%rowtype;
begin
  if auth.uid() is null then
    raise exception 'You must be signed in to register as a lecturer.';
  end if;
  if exists (select 1 from public.lecturer_slots where claimed_by = auth.uid()) then
    raise exception 'This account is already registered as a lecturer.';
  end if;

  select * into v_slot from public.lecturer_slots where lecturer_id = v_key for update;
  if not found then
    raise exception 'Invalid Lecturer ID.';
  end if;
  if v_slot.claimed_at is not null then
    raise exception 'This Lecturer ID has already been claimed.';
  end if;

  update public.lecturer_slots
     set claimed_by = auth.uid(), claimed_at = now()
   where lecturer_id = v_key;

  delete from public.user_roles where user_id = auth.uid();
  insert into public.user_roles (user_id, role) values (auth.uid(), 'teacher');

  return v_slot.course_id;
end;
$$;


-- 3.4 lecturer content publishing (legacy helpers, still present) -----------

create or replace function public.publish_teacher_note(
  _course_id uuid, _topic_title text, _lesson_title text, _body_md text
)
returns uuid
language plpgsql security definer set search_path = public
as $$
declare
  v_topic_id uuid;
  v_lesson_id uuid;
  v_teacher_name text;
  v_course_title text;
begin
  if not public.has_role(auth.uid(), 'teacher'::public.app_role) then
    raise exception 'Only teachers can publish materials';
  end if;
  if _course_id is distinct from public.current_lecturer_course() then
    raise exception 'You can only publish content to your assigned course.';
  end if;

  select title into v_course_title from public.courses where id = _course_id;
  if v_course_title is null then raise exception 'Course not found'; end if;

  select id into v_topic_id from public.topics
    where course_id = _course_id and lower(title) = lower(trim(_topic_title)) limit 1;
  if v_topic_id is null then
    insert into public.topics (course_id, slug, title, order_index)
    values (
      _course_id,
      trim(both '-' from regexp_replace(lower(trim(_topic_title)), '[^a-z0-9]+', '-', 'g')),
      trim(_topic_title),
      coalesce((select max(order_index) + 1 from public.topics where course_id = _course_id), 0)
    ) returning id into v_topic_id;
  end if;

  insert into public.lessons (topic_id, modality, title, body_md, order_index)
  values (
    v_topic_id, 'text', trim(_lesson_title), coalesce(_body_md, ''),
    coalesce((select max(order_index) + 1 from public.lessons where topic_id = v_topic_id), 0)
  ) returning id into v_lesson_id;

  select coalesce(nullif(trim(full_name), ''), 'Your teacher') into v_teacher_name
    from public.profiles where id = auth.uid();
  insert into public.notifications (user_id, course_id, kind, title, message)
    select e.user_id, _course_id, 'note', 'New course note',
      v_teacher_name || ' posted "' || trim(_lesson_title) || '" in ' || v_course_title || '.'
    from public.enrollments e where e.course_id = _course_id and e.user_id <> auth.uid();
  return v_lesson_id;
end;
$$;

create or replace function public.publish_teacher_quiz(
  _course_id uuid, _topic_title text, _quiz_title text, _questions jsonb
)
returns uuid
language plpgsql security definer set search_path = public
as $$
declare
  v_topic_id uuid;
  v_quiz_id uuid := gen_random_uuid();
  v_teacher_name text;
  v_course_title text;
  q jsonb;
begin
  if not public.has_role(auth.uid(), 'teacher'::public.app_role) then
    raise exception 'Only teachers can publish materials';
  end if;
  if _course_id is distinct from public.current_lecturer_course() then
    raise exception 'You can only publish content to your assigned course.';
  end if;
  if jsonb_typeof(_questions) <> 'array' or jsonb_array_length(_questions) = 0 then
    raise exception 'At least one quiz question is required';
  end if;
  select title into v_course_title from public.courses where id = _course_id;
  if v_course_title is null then raise exception 'Course not found'; end if;

  select id into v_topic_id from public.topics
    where course_id = _course_id and lower(title) = lower(trim(_topic_title)) limit 1;
  if v_topic_id is null then
    insert into public.topics (course_id, slug, title, order_index)
    values (
      _course_id,
      trim(both '-' from regexp_replace(lower(trim(_topic_title)), '[^a-z0-9]+', '-', 'g')),
      trim(_topic_title),
      coalesce((select max(order_index) + 1 from public.topics where course_id = _course_id), 0)
    ) returning id into v_topic_id;
  end if;

  for q in select value from jsonb_array_elements(_questions)
  loop
    insert into public.questions (topic_id, prompt, choices, correct_index, explanation, difficulty)
    values (
      v_topic_id, q->>'prompt', q->'choices', (q->>'correct_index')::int,
      nullif(q->>'explanation', ''), coalesce((q->>'difficulty')::int, 2)
    );
  end loop;

  select coalesce(nullif(trim(full_name), ''), 'Your teacher') into v_teacher_name
    from public.profiles where id = auth.uid();
  insert into public.notifications (user_id, course_id, kind, title, message)
    select e.user_id, _course_id, 'quiz', 'New quiz available',
      v_teacher_name || ' posted "' || trim(_quiz_title) || '" in ' || v_course_title || '.'
    from public.enrollments e where e.course_id = _course_id and e.user_id <> auth.uid();
  return v_quiz_id;
end;
$$;


-- 3.5 quiz question retrieval (sanitized — no answer key) -------------------

create or replace function public.get_quiz_questions(_topic_id uuid, _limit int default 5)
returns table (id uuid, prompt text, choices jsonb, difficulty int)
language sql stable security definer set search_path = public
as $$
  select id, prompt, choices, difficulty
  from public.questions
  where topic_id = _topic_id
  order by random()
  limit greatest(coalesce(_limit, 5), 1);
$$;

create or replace function public.get_course_quiz_questions(_quiz_id uuid, _limit int default 30)
returns table (id uuid, prompt text, choices jsonb, difficulty int)
language sql stable security definer set search_path = public
as $$
  select q.id, q.prompt, q.choices, q.difficulty
  from public.questions q
  where q.course_quiz_id = _quiz_id
  order by random()
  limit greatest(coalesce(_limit, 30), 1);
$$;


-- 3.6 grading (server-authoritative, idempotent, row-locked) ---------------

create or replace function public.grade_quiz(
  _attempt_id uuid, _answers jsonb, _timed_out boolean default false
)
returns table (question_id uuid, is_correct boolean, correct_index int, explanation text)
language plpgsql security definer set search_path = public
as $$
declare
  v_user uuid;
  v_topic_id uuid;
  v_cq_id uuid;
  v_finished timestamptz;
  v_expires timestamptz;
  v_cq_deadline timestamptz;
  v_lesson_id uuid;
  v_total int := 0;
  v_answered int := 0;
  v_score int := 0;
  rec record;
  v_sel int;
begin
  select user_id, topic_id, course_quiz_id, finished_at, expires_at
    into v_user, v_topic_id, v_cq_id, v_finished, v_expires
    from public.quiz_attempts where id = _attempt_id
    for update;
  if v_user is null or v_user <> auth.uid() then
    raise exception 'forbidden';
  end if;

  if v_finished is not null then
    return query
      select aa.question_id, aa.is_correct, q.correct_index, q.explanation
      from public.attempt_answers aa
      join public.questions q on q.id = aa.question_id
      where aa.attempt_id = _attempt_id;
    return;
  end if;

  if v_topic_id is not null then
    select count(*) into v_total from public.questions where topic_id = v_topic_id;
    if v_total = 0 then
      raise exception 'This module does not have a quiz yet.';
    end if;
  elsif v_cq_id is not null then
    select count(*) into v_total from public.questions where course_quiz_id = v_cq_id;
    if v_total = 0 then
      raise exception 'This course does not have a general quiz yet.';
    end if;
    select deadline into v_cq_deadline from public.course_quizzes where id = v_cq_id;
  else
    raise exception 'This quiz attempt is not linked to a quiz.';
  end if;

  -- UPSERT every answer the client submitted (may be '{}' on timeout-finalize).
  for rec in
    select q.id, q.correct_index
    from public.questions q
    where q.id::text in (select jsonb_object_keys(_answers))
      and (
        (v_topic_id is not null and q.topic_id = v_topic_id)
        or (v_cq_id is not null and q.course_quiz_id = v_cq_id)
      )
  loop
    v_sel := (_answers ->> rec.id::text)::int;
    insert into public.attempt_answers (attempt_id, question_id, selected_index, is_correct)
    values (_attempt_id, rec.id, v_sel, v_sel = rec.correct_index)
    on conflict (attempt_id, question_id)
    do update set selected_index = excluded.selected_index,
                  is_correct     = excluded.is_correct;
  end loop;

  -- Authoritative totals from everything persisted for this attempt (incremental
  -- Quiz Recovery saves + this submission).
  select count(*), count(*) filter (where aa.is_correct)
    into v_answered, v_score
    from public.attempt_answers aa
    where aa.attempt_id = _attempt_id;

  update public.quiz_attempts
    set score = v_score,
        total = v_total,
        answered_count = v_answered,
        finished_at = now(),
        timed_out = _timed_out
          or (v_expires is not null and now() >= v_expires)
          or (v_cq_deadline is not null and now() >= v_cq_deadline)
    where id = _attempt_id;

  if v_topic_id is not null then
    select id into v_lesson_id from public.lessons
      where topic_id = v_topic_id order by order_index, id limit 1;
    if v_lesson_id is not null then
      insert into public.progress (user_id, lesson_id, watched_seconds, completed_at, updated_at)
      values (v_user, v_lesson_id, 0, now(), now())
      on conflict (user_id, lesson_id) do update
        set completed_at = coalesce(public.progress.completed_at, excluded.completed_at),
            updated_at = now();
    end if;
  end if;

  return query
    select aa.question_id, aa.is_correct, q.correct_index, q.explanation
    from public.attempt_answers aa
    join public.questions q on q.id = aa.question_id
    where aa.attempt_id = _attempt_id;
end;
$$;

-- Persist one selected answer for the caller's OWN in-progress attempt, mid-quiz.
-- Idempotent UPSERT on (attempt_id, question_id) — changing an answer overwrites.
-- Rejects a finished / expired attempt and any question outside the attempt's
-- quiz. Returns nothing: correctness is never revealed while the quiz is live.
create or replace function public.save_quiz_answer(
  _attempt_id uuid, _question_id uuid, _selected_index int
)
returns void
language plpgsql security definer set search_path = public
as $$
declare
  v_user uuid; v_topic uuid; v_cq uuid;
  v_finished timestamptz; v_expires timestamptz; v_correct int;
  v_cq_deadline timestamptz;
begin
  select user_id, topic_id, course_quiz_id, finished_at, expires_at
    into v_user, v_topic, v_cq, v_finished, v_expires
    from public.quiz_attempts where id = _attempt_id for update;

  if v_user is null or v_user <> auth.uid() then
    raise exception 'forbidden';
  end if;
  if v_finished is not null then
    raise exception 'This attempt has already been submitted.';
  end if;
  if v_expires is not null and now() >= v_expires then
    raise exception 'This attempt has run out of time.';
  end if;
  -- General Course Quiz: the quiz deadline is an absolute upper bound, applied
  -- live even if a lecturer shortened it after this attempt started.
  if v_cq is not null then
    select deadline into v_cq_deadline from public.course_quizzes where id = v_cq;
    if v_cq_deadline is not null and now() >= v_cq_deadline then
      raise exception 'This attempt has run out of time.';
    end if;
  end if;
  if _selected_index is null or _selected_index < 0 then
    raise exception 'Invalid answer.';
  end if;

  select q.correct_index into v_correct
  from public.questions q
  where q.id = _question_id
    and (
      (v_topic is not null and q.topic_id = v_topic)
      or (v_cq is not null and q.course_quiz_id = v_cq)
    );
  if v_correct is null then
    raise exception 'That question is not part of this quiz.';
  end if;

  insert into public.attempt_answers (attempt_id, question_id, selected_index, is_correct)
  values (_attempt_id, _question_id, _selected_index, _selected_index = v_correct)
  on conflict (attempt_id, question_id)
  do update set selected_index = excluded.selected_index,
                is_correct     = excluded.is_correct;
end;
$$;

-- The caller's previously selected answers (question_id + selected_index only)
-- for their own attempt — used to restore an in-progress quiz on resume. Never
-- returns is_correct / correct_index / explanation.
create or replace function public.get_attempt_answers(_attempt_id uuid)
returns table (question_id uuid, selected_index int)
language sql stable security definer set search_path = public
as $$
  select aa.question_id, aa.selected_index
  from public.attempt_answers aa
  join public.quiz_attempts a on a.id = aa.attempt_id
  where aa.attempt_id = _attempt_id
    and a.user_id = auth.uid();
$$;

-- Grade the caller's own timed-out attempts (module or general) never submitted.
-- A General Course Quiz attempt is also finalised once its quiz deadline passes,
-- not only when its own normal timer runs out.
create or replace function public.finalize_expired_quiz_attempts()
returns int
language plpgsql security definer set search_path = public
as $$
declare
  v_id uuid;
  v_count int := 0;
begin
  for v_id in
    select a.id
    from public.quiz_attempts a
    where a.user_id = auth.uid()
      and (a.topic_id is not null or a.course_quiz_id is not null)
      and a.finished_at is null
      and a.expires_at is not null
      and (
        now() >= a.expires_at
        or exists (
          select 1 from public.course_quizzes cq
          where cq.id = a.course_quiz_id
            and cq.deadline is not null
            and now() >= cq.deadline
        )
      )
  loop
    perform public.grade_quiz(v_id, '{}'::jsonb, true);
    v_count := v_count + 1;
  end loop;
  return v_count;
end;
$$;


-- 3.7 lecturer: module creation + quiz replace ----------------------------

create or replace function public.create_module_with_quiz(
  _title text, _summary text, _lessons jsonb, _questions jsonb,
  _duration_minutes int default 30
)
returns uuid
language plpgsql security definer set search_path = public
as $$
declare
  v_course uuid;
  v_topic_id uuid;
  v_slug text;
  v_order int;
  v_i int := 0;
  v_duration int;
  l jsonb;
  q jsonb;
  v_modality text;
begin
  v_course := public.current_lecturer_course();
  if v_course is null then
    raise exception 'Only a lecturer can create a module.';
  end if;
  if coalesce(trim(_title), '') = '' then
    raise exception 'A module title is required.';
  end if;
  if char_length(trim(_title)) > 200 then
    raise exception 'The module title is too long.';
  end if;
  if _lessons is null or jsonb_typeof(_lessons) <> 'array' or jsonb_array_length(_lessons) < 1 then
    raise exception 'A module needs at least one course content before it can be created.';
  end if;
  if _questions is null or jsonb_typeof(_questions) <> 'array' or jsonb_array_length(_questions) < 1 then
    raise exception 'A quiz with at least one question is required before this module can be created.';
  end if;
  if jsonb_array_length(_questions) > 50 then
    raise exception 'A quiz can have at most 50 questions.';
  end if;

  v_duration := least(greatest(coalesce(_duration_minutes, 30), 1), 240);

  v_slug := trim(both '-' from regexp_replace(lower(trim(_title)), '[^a-z0-9]+', '-', 'g'));
  if v_slug = '' then v_slug := 'module'; end if;
  if exists (select 1 from public.topics where course_id = v_course and slug = v_slug) then
    v_slug := v_slug || '-' || substr(md5(random()::text), 1, 6);
  end if;

  v_order := coalesce((select max(order_index) + 1 from public.topics where course_id = v_course), 0);

  insert into public.topics (course_id, slug, title, summary, order_index, quiz_duration_minutes)
  values (v_course, v_slug, trim(_title), nullif(trim(coalesce(_summary, '')), ''), v_order, v_duration)
  returning id into v_topic_id;

  v_i := 0;
  for l in select value from jsonb_array_elements(_lessons)
  loop
    v_modality := coalesce(nullif(l->>'modality', ''), 'text');
    if coalesce(trim(l->>'title'), '') = '' then
      raise exception 'Each course content needs a title.';
    end if;
    if v_modality = 'text' then
      if coalesce(trim(l->>'body_md'), '') = '' then
        raise exception 'A text lesson needs content.';
      end if;
    else
      if coalesce(trim(l->>'media_url'), '') = '' then
        raise exception 'A % lesson needs a file or link.', v_modality;
      end if;
    end if;

    insert into public.lessons (topic_id, modality, title, body_md, media_url, order_index)
    values (
      v_topic_id, v_modality::public.modality, trim(l->>'title'),
      nullif(trim(coalesce(l->>'body_md', '')), ''),
      nullif(trim(coalesce(l->>'media_url', '')), ''), v_i
    );
    v_i := v_i + 1;
  end loop;

  v_i := 0;
  for q in select value from jsonb_array_elements(_questions)
  loop
    insert into public.questions
      (topic_id, prompt, choices, correct_index, explanation, difficulty, order_index)
    values (
      v_topic_id, q->>'prompt', q->'choices', (q->>'correct_index')::int,
      nullif(q->>'explanation', ''), coalesce((q->>'difficulty')::int, 3), v_i
    );
    v_i := v_i + 1;
  end loop;

  return v_topic_id;
end;
$$;

create or replace function public.replace_topic_quiz(_topic_id uuid, _questions jsonb)
returns void
language plpgsql security definer set search_path = public
as $$
declare
  v_course uuid;
  v_n int;
  v_i int := 0;
  q jsonb;
begin
  v_course := public.current_lecturer_course();
  if v_course is null then
    raise exception 'Only a lecturer can edit this quiz.';
  end if;
  if not exists (select 1 from public.topics where id = _topic_id and course_id = v_course) then
    raise exception 'You can only edit quizzes for modules in your assigned course.';
  end if;
  if _questions is null or jsonb_typeof(_questions) <> 'array' then
    raise exception 'A quiz is required.';
  end if;
  v_n := jsonb_array_length(_questions);
  if v_n < 1 then raise exception 'A quiz must have at least one question.'; end if;
  if v_n > 50 then raise exception 'A quiz can have at most 50 questions.'; end if;

  delete from public.questions where topic_id = _topic_id;

  for q in select value from jsonb_array_elements(_questions)
  loop
    insert into public.questions
      (topic_id, prompt, choices, correct_index, explanation, difficulty, order_index)
    values (
      _topic_id, q->>'prompt', q->'choices', (q->>'correct_index')::int,
      nullif(q->>'explanation', ''), coalesce((q->>'difficulty')::int, 3), v_i
    );
    v_i := v_i + 1;
  end loop;
end;
$$;


-- 3.8 lecturer: general course quiz management ---------------------------

-- A due date, when set together with an available-from date, must be strictly
-- later. Enforced in every general-quiz writer below.

create or replace function public.create_course_quiz(
  _title text, _description text default null, _deadline timestamptz default null,
  _max_attempts int default null, _duration_minutes int default 30,
  _available_from timestamptz default null
)
returns uuid
language plpgsql security definer set search_path = public
as $$
declare
  v_course uuid;
  v_id uuid;
  v_title text;
begin
  v_course := public.current_lecturer_course();
  if v_course is null then
    raise exception 'Only a lecturer can create a general course quiz.';
  end if;
  if _max_attempts is not null and _max_attempts < 1 then
    raise exception 'Maximum attempts must be at least 1, or unlimited.';
  end if;
  if _deadline is not null and _available_from is not null and _deadline <= _available_from then
    raise exception 'The due date must be after the available-from date.';
  end if;

  v_title := nullif(btrim(coalesce(_title, '')), '');
  if v_title is null then v_title := 'General Course Quiz'; end if;

  insert into public.course_quizzes
    (course_id, title, description, deadline, max_attempts, duration_minutes, available_from)
  values (
    v_course, v_title, nullif(btrim(coalesce(_description, '')), ''),
    _deadline, _max_attempts, least(greatest(coalesce(_duration_minutes, 30), 1), 240),
    _available_from
  )
  returning id into v_id;
  return v_id;
end;
$$;

create or replace function public.create_course_quiz_with_questions(
  _title text, _questions jsonb, _description text default null,
  _deadline timestamptz default null, _max_attempts int default null,
  _duration_minutes int default 30, _available_from timestamptz default null
)
returns uuid
language plpgsql security definer set search_path = public
as $$
declare
  v_course uuid;
  v_id uuid;
  v_title text;
  v_i int := 0;
  q jsonb;
begin
  v_course := public.current_lecturer_course();
  if v_course is null then
    raise exception 'Only a lecturer can create a general course quiz.';
  end if;
  if _max_attempts is not null and _max_attempts < 1 then
    raise exception 'Maximum attempts must be at least 1, or unlimited.';
  end if;
  if _deadline is not null and _available_from is not null and _deadline <= _available_from then
    raise exception 'The due date must be after the available-from date.';
  end if;
  if _questions is null or jsonb_typeof(_questions) <> 'array' or jsonb_array_length(_questions) < 1 then
    raise exception 'A general course quiz needs at least one question before it can be created.';
  end if;
  if jsonb_array_length(_questions) > 50 then
    raise exception 'A quiz can have at most 50 questions.';
  end if;

  v_title := nullif(btrim(coalesce(_title, '')), '');
  if v_title is null then v_title := 'General Course Quiz'; end if;

  insert into public.course_quizzes
    (course_id, title, description, deadline, max_attempts, duration_minutes, available_from)
  values (
    v_course, v_title, nullif(btrim(coalesce(_description, '')), ''),
    _deadline, _max_attempts, least(greatest(coalesce(_duration_minutes, 30), 1), 240),
    _available_from
  )
  returning id into v_id;

  for q in select value from jsonb_array_elements(_questions)
  loop
    insert into public.questions
      (course_quiz_id, prompt, choices, correct_index, explanation, difficulty, order_index)
    values (
      v_id, q->>'prompt', q->'choices', (q->>'correct_index')::int,
      nullif(q->>'explanation', ''), coalesce((q->>'difficulty')::int, 3), v_i
    );
    v_i := v_i + 1;
  end loop;

  return v_id;
end;
$$;

create or replace function public.update_course_quiz(
  _quiz_id uuid, _title text, _description text default null,
  _deadline timestamptz default null, _max_attempts int default null,
  _duration_minutes int default 30, _available_from timestamptz default null
)
returns void
language plpgsql security definer set search_path = public
as $$
declare
  v_course uuid;
  v_title text;
begin
  v_course := public.current_lecturer_course();
  if v_course is null then
    raise exception 'Only a lecturer can edit a general course quiz.';
  end if;
  if not exists (select 1 from public.course_quizzes where id = _quiz_id and course_id = v_course) then
    raise exception 'This general course quiz is not part of your course.';
  end if;
  if _max_attempts is not null and _max_attempts < 1 then
    raise exception 'Maximum attempts must be at least 1, or unlimited.';
  end if;
  if _deadline is not null and _available_from is not null and _deadline <= _available_from then
    raise exception 'The due date must be after the available-from date.';
  end if;

  v_title := nullif(btrim(coalesce(_title, '')), '');
  if v_title is null then v_title := 'General Course Quiz'; end if;

  update public.course_quizzes
     set title = v_title,
         description = nullif(btrim(coalesce(_description, '')), ''),
         deadline = _deadline,
         max_attempts = _max_attempts,
         duration_minutes = least(greatest(coalesce(_duration_minutes, 30), 1), 240),
         available_from = _available_from
   where id = _quiz_id and course_id = v_course;
end;
$$;

create or replace function public.delete_course_quiz(_quiz_id uuid)
returns void
language plpgsql security definer set search_path = public
as $$
declare
  v_course uuid;
begin
  v_course := public.current_lecturer_course();
  if v_course is null then
    raise exception 'Only a lecturer can delete a general course quiz.';
  end if;
  delete from public.course_quizzes where id = _quiz_id and course_id = v_course;
  if not found then
    raise exception 'This general course quiz is not part of your course.';
  end if;
end;
$$;

create or replace function public.replace_course_quiz(_quiz_id uuid, _questions jsonb)
returns uuid
language plpgsql security definer set search_path = public
as $$
declare
  v_course uuid;
  v_n int;
  v_i int := 0;
  q jsonb;
begin
  v_course := public.current_lecturer_course();
  if v_course is null then
    raise exception 'Only a lecturer can edit a general course quiz.';
  end if;
  if not exists (select 1 from public.course_quizzes where id = _quiz_id and course_id = v_course) then
    raise exception 'This general course quiz is not part of your course.';
  end if;
  if _questions is null or jsonb_typeof(_questions) <> 'array' then
    raise exception 'A quiz is required.';
  end if;
  v_n := jsonb_array_length(_questions);
  if v_n < 1 then raise exception 'A quiz must have at least one question.'; end if;
  if v_n > 50 then raise exception 'A quiz can have at most 50 questions.'; end if;

  delete from public.questions where course_quiz_id = _quiz_id;

  for q in select value from jsonb_array_elements(_questions)
  loop
    insert into public.questions
      (course_quiz_id, prompt, choices, correct_index, explanation, difficulty, order_index)
    values (
      _quiz_id, q->>'prompt', q->'choices', (q->>'correct_index')::int,
      nullif(q->>'explanation', ''), coalesce((q->>'difficulty')::int, 3), v_i
    );
    v_i := v_i + 1;
  end loop;

  return _quiz_id;
end;
$$;

create or replace function public.course_quiz_has_attempts(_quiz_id uuid)
returns boolean
language sql stable security definer set search_path = public
as $$
  select exists (
    select 1
    from public.quiz_attempts a
    join public.course_quizzes cq on cq.id = a.course_quiz_id
    where a.course_quiz_id = _quiz_id
      and cq.course_id = public.current_lecturer_course()
  );
$$;

create or replace function public.list_course_quizzes(_course_id uuid)
returns table (
  id uuid, title text, description text, deadline timestamptz,
  created_at timestamptz, question_count bigint, max_attempts int, duration_minutes int,
  available_from timestamptz
)
language sql stable security definer set search_path = public
as $$
  select
    cq.id, cq.title, cq.description, cq.deadline, cq.created_at,
    (select count(*) from public.questions q where q.course_quiz_id = cq.id),
    cq.max_attempts, cq.duration_minutes, cq.available_from
  from public.course_quizzes cq
  where cq.course_id = _course_id
  order by cq.created_at;
$$;

-- Per general quiz in the caller's managed course: enrolled student count and
-- the number with a finished attempt. Lecturer-scoped; empty for anyone else.
create or replace function public.get_course_quiz_submission_stats()
returns table (course_quiz_id uuid, enrolled int, submitted int)
language sql stable security definer set search_path = public
as $$
  with lc as (select public.current_lecturer_course() as course_id)
  select
    cq.id,
    (select count(*)::int from public.enrollments e where e.course_id = cq.course_id),
    (select count(distinct a.user_id)::int
       from public.quiz_attempts a
       where a.course_quiz_id = cq.id and a.finished_at is not null)
  from lc
  join public.course_quizzes cq on cq.course_id = lc.course_id;
$$;


-- 3.9 lecturer analytics --------------------------------------------------

create or replace function public.get_course_students()
returns table (
  user_id uuid, full_name text, avatar_url text, enrolled_at timestamptz,
  attempts integer, avg_pct integer, last_active timestamptz
)
language sql stable security definer set search_path = public
as $$
  with lc as (select public.current_lecturer_course() as course_id)
  select
    p.id, p.full_name, p.avatar_url, e.created_at,
    count(a.id) filter (where a.finished_at is not null)::integer,
    coalesce(
      round(avg((a.score::numeric / nullif(a.total, 0)) * 100)
            filter (where a.finished_at is not null)),
      0
    )::integer,
    max(a.started_at)
  from lc
  join public.enrollments e on e.course_id = lc.course_id
  join public.profiles p on p.id = e.user_id
  left join public.quiz_attempts a
    on a.user_id = e.user_id
   and a.topic_id in (select t.id from public.topics t where t.course_id = lc.course_id)
  group by p.id, p.full_name, p.avatar_url, e.created_at;
$$;

create or replace function public.get_course_quiz_performance()
returns table (
  attempt_id uuid, student text, quiz_type text, quiz_title text,
  topic text, topic_id uuid, course_quiz_id uuid,
  score integer, total integer, pct integer, answered_count integer,
  started_at timestamptz, finished_at timestamptz,
  completed boolean, timed_out boolean, expired boolean
)
language sql stable security definer set search_path = public
as $$
  with lc as (select public.current_lecturer_course() as course_id)
  select
    a.id, p.full_name, 'module'::text, t.title, t.title, t.id, null::uuid,
    a.score, a.total,
    case when a.total > 0 then round(a.score::numeric / a.total * 100)::integer else 0 end,
    a.answered_count, a.started_at, a.finished_at,
    a.finished_at is not null, a.timed_out,
    a.finished_at is null and a.expires_at is not null and now() >= a.expires_at
  from lc
  join public.topics t on t.course_id = lc.course_id
  join public.quiz_attempts a on a.topic_id = t.id
  join public.profiles p on p.id = a.user_id

  union all

  select
    a.id, p.full_name, 'general'::text, cq.title, null::text, null::uuid, cq.id,
    a.score, a.total,
    case when a.total > 0 then round(a.score::numeric / a.total * 100)::integer else 0 end,
    a.answered_count, a.started_at, a.finished_at,
    a.finished_at is not null, a.timed_out,
    a.finished_at is null and a.expires_at is not null and now() >= a.expires_at
  from lc
  join public.course_quizzes cq on cq.course_id = lc.course_id
  join public.quiz_attempts a on a.course_quiz_id = cq.id
  join public.profiles p on p.id = a.user_id

  order by started_at desc;
$$;

-- Raw finished MODULE-quiz attempts for students enrolled in the caller's
-- managed course. General Course Quiz attempts are excluded (a.topic_id = t.id).
-- src/lib/mastery.ts turns these into per-module / course mastery. Zero rows for
-- a non-lecturer or another lecturer's course.
create or replace function public.get_course_student_mastery()
returns table (
  user_id        uuid,
  full_name      text,
  attempt_id     uuid,
  topic_id       uuid,
  topic_title    text,
  score          integer,
  total          integer,
  answered_count integer,
  started_at     timestamptz,
  finished_at    timestamptz
)
language sql stable security definer set search_path = public
as $$
  with lc as (select public.current_lecturer_course() as course_id)
  select
    a.user_id, p.full_name, a.id, a.topic_id, t.title,
    a.score, a.total, a.answered_count, a.started_at, a.finished_at
  from lc
  join public.topics t        on t.course_id = lc.course_id
  join public.quiz_attempts a on a.topic_id = t.id and a.finished_at is not null
  join public.profiles p      on p.id = a.user_id
  where exists (
    select 1 from public.enrollments e
    where e.course_id = lc.course_id and e.user_id = a.user_id
  );
$$;


-- 3.10 study paths -------------------------------------------------------

create or replace function public.save_study_path(
  _attempt_id uuid, _content jsonb, _weak_question_ids uuid[]
)
returns public.study_paths
language plpgsql security definer set search_path = public
as $$
declare
  v_uid uuid := auth.uid();
  v_existing public.study_paths;
  v_att record;
  v_topic uuid;
  v_course uuid;
  v_row public.study_paths;
begin
  if v_uid is null then raise exception 'AUTH_REQUIRED'; end if;

  select * into v_existing from public.study_paths where attempt_id = _attempt_id;
  if found then
    if v_existing.user_id <> v_uid then raise exception 'ATTEMPT_NOT_OWNED'; end if;
    return v_existing;
  end if;

  select id, user_id, topic_id, course_quiz_id, finished_at
    into v_att
  from public.quiz_attempts where id = _attempt_id;

  if not found then raise exception 'ATTEMPT_NOT_FOUND'; end if;
  if v_att.user_id <> v_uid then raise exception 'ATTEMPT_NOT_OWNED'; end if;
  if v_att.finished_at is null then raise exception 'ATTEMPT_NOT_FINISHED'; end if;
  if _content is null or jsonb_typeof(_content) <> 'object' then
    raise exception 'INVALID_CONTENT';
  end if;

  if v_att.topic_id is not null then
    v_topic := v_att.topic_id;
    select course_id into v_course from public.topics where id = v_att.topic_id;
  elsif v_att.course_quiz_id is not null then
    v_topic := null;
    select course_id into v_course from public.course_quizzes where id = v_att.course_quiz_id;
  else
    raise exception 'ATTEMPT_NOT_LINKED';
  end if;

  if v_course is null then raise exception 'COURSE_NOT_FOUND'; end if;

  insert into public.study_paths
    (user_id, topic_id, course_id, attempt_id, weak_question_ids, content)
  values (v_uid, v_topic, v_course, _attempt_id, coalesce(_weak_question_ids, '{}'::uuid[]), _content)
  on conflict (attempt_id) do nothing
  returning * into v_row;

  if v_row.id is null then
    select * into v_row from public.study_paths where attempt_id = _attempt_id;
  end if;

  return v_row;
end;
$$;

create or replace function public.mark_study_path_completed(_id uuid)
returns public.study_paths
language plpgsql security definer set search_path = public
as $$
declare
  v_uid uuid := auth.uid();
  v_row public.study_paths;
begin
  if v_uid is null then raise exception 'AUTH_REQUIRED'; end if;

  update public.study_paths
     set completed_at = coalesce(completed_at, now())
   where id = _id and user_id = v_uid
  returning * into v_row;

  if v_row.id is null then raise exception 'STUDY_PATH_NOT_FOUND'; end if;
  return v_row;
end;
$$;

-- Dormant in the current app UI, kept in the schema for compatibility.
create or replace function public.set_study_path_saved(_id uuid, _saved boolean)
returns public.study_paths
language plpgsql security definer set search_path = public
as $$
declare
  v_uid uuid := auth.uid();
  v_row public.study_paths;
begin
  if v_uid is null then raise exception 'AUTH_REQUIRED'; end if;

  update public.study_paths
     set saved_at = case when _saved then coalesce(saved_at, now()) else null end
   where id = _id and user_id = v_uid
  returning * into v_row;

  if v_row.id is null then raise exception 'STUDY_PATH_NOT_FOUND'; end if;
  return v_row;
end;
$$;

create or replace function public.delete_study_path(_id uuid)
returns void
language plpgsql security definer set search_path = public
as $$
declare
  v_uid uuid := auth.uid();
  v_deleted uuid;
begin
  if v_uid is null then raise exception 'AUTH_REQUIRED'; end if;

  delete from public.study_paths
   where id = _id and user_id = v_uid
  returning id into v_deleted;

  if v_deleted is null then raise exception 'STUDY_PATH_NOT_FOUND'; end if;
end;
$$;


-- 3.11 trigger functions: quiz-attempt guards --------------------------

-- BEFORE INSERT: stamp expires_at from the topic's / course quiz's duration.
-- This is the student's NORMAL, immutable timer. A General Course Quiz deadline
-- is NOT applied here — it is enforced dynamically as least(expires_at, deadline)
-- by save_quiz_answer / finalize_expired_quiz_attempts / grade_quiz (and mirrored
-- client-side by effectiveQuizDeadline()), so moving the deadline earlier reduces
-- effective time immediately and moving it later never extends past this stamp.
create or replace function public.stamp_quiz_attempt_expiry()
returns trigger
language plpgsql security definer set search_path = public
as $$
declare
  v_minutes int;
begin
  if new.topic_id is not null then
    select quiz_duration_minutes into v_minutes from public.topics where id = new.topic_id;
  elsif new.course_quiz_id is not null then
    select duration_minutes into v_minutes from public.course_quizzes where id = new.course_quiz_id;
  else
    return new;
  end if;
  new.expires_at := coalesce(new.started_at, now())
    + make_interval(mins => coalesce(v_minutes, 30));
  return new;
end;
$$;

-- BEFORE INSERT: enrolment + availability + deadline + attempt-cap for
-- general-quiz attempts.
create or replace function public.enforce_course_quiz_attempt()
returns trigger
language plpgsql security definer set search_path = public
as $$
declare
  v_deadline timestamptz;
  v_available_from timestamptz;
  v_course uuid;
  v_max int;
  v_used int;
begin
  if new.course_quiz_id is null then
    return new;
  end if;

  select deadline, available_from, course_id, max_attempts
    into v_deadline, v_available_from, v_course, v_max
    from public.course_quizzes
    where id = new.course_quiz_id;

  if v_course is null then
    raise exception 'This assessment no longer exists.';
  end if;

  if public.current_lecturer_course() is distinct from v_course
     and not exists (
       select 1 from public.enrollments e
       where e.course_id = v_course and e.user_id = auth.uid()
     ) then
    raise exception 'You must be enrolled in this course to take this assessment.';
  end if;

  if v_available_from is not null and now() < v_available_from then
    raise exception 'This assessment is not available yet.';
  end if;

  if v_deadline is not null and now() >= v_deadline then
    raise exception 'This assessment is no longer available because the deadline has passed.';
  end if;

  if v_max is not null then
    perform pg_advisory_xact_lock(
      hashtext(new.course_quiz_id::text),
      hashtext(new.user_id::text)
    );
    select count(*) into v_used
      from public.quiz_attempts
      where course_quiz_id = new.course_quiz_id
        and user_id = new.user_id;
    if v_used >= v_max then
      raise exception 'You have used all % attempt(s) allowed for this assessment.', v_max;
    end if;
  end if;

  return new;
end;
$$;


-- 3.12 trigger functions: "a quiz must keep at least one question" ------

create or replace function public.assert_topic_has_questions()
returns trigger
language plpgsql security definer set search_path = public
as $$
begin
  if old.topic_id is not null
     and exists (select 1 from public.topics where id = old.topic_id)
     and not exists (select 1 from public.questions where topic_id = old.topic_id)
  then
    raise exception 'A module quiz must have at least one question.';
  end if;
  return null;
end;
$$;

create or replace function public.assert_course_quiz_has_questions()
returns trigger
language plpgsql security definer set search_path = public
as $$
begin
  if old.course_quiz_id is not null
     and exists (select 1 from public.course_quizzes where id = old.course_quiz_id)
     and not exists (select 1 from public.questions where course_quiz_id = old.course_quiz_id)
  then
    raise exception 'A general course quiz must keep at least one question.';
  end if;
  return null;
end;
$$;


-- 3.13 trigger functions: notifications --------------------------------

create or replace function public.notify_new_lesson()
returns trigger
language plpgsql security definer set search_path = public
as $$
declare
  v_actor uuid := auth.uid();
  v_course_id uuid;
  v_course_title text;
  v_topic_title text;
begin
  select t.course_id, t.title, c.title
    into v_course_id, v_topic_title, v_course_title
  from public.topics t
  join public.courses c on c.id = t.course_id
  where t.id = new.topic_id;
  if v_course_id is null then return new; end if;

  insert into public.notifications (user_id, course_id, topic_id, audience, kind, title, message)
  select e.user_id, v_course_id, new.topic_id, 'student', 'material',
    'New learning material',
    'A new ' || new.modality::text || ' lesson "' || new.title || '" was added to '
      || v_topic_title || ' in ' || v_course_title || '.'
  from public.enrollments e
  where e.course_id = v_course_id and e.user_id is distinct from v_actor;

  return new;
end;
$$;

create or replace function public.notify_new_module()
returns trigger
language plpgsql security definer set search_path = public
as $$
declare
  v_actor uuid := auth.uid();
  v_course_title text;
begin
  select c.title into v_course_title from public.courses c where c.id = new.course_id;
  if v_course_title is null then return new; end if;

  insert into public.notifications (user_id, course_id, topic_id, audience, kind, title, message)
  select e.user_id, new.course_id, new.id, 'student', 'module_quiz',
    'New module quiz',
    'A new module "' || new.title || '" with a module quiz is now available in '
      || v_course_title || '.'
  from public.enrollments e
  where e.course_id = new.course_id and e.user_id is distinct from v_actor;

  return new;
end;
$$;

create or replace function public.notify_new_general_quiz()
returns trigger
language plpgsql security definer set search_path = public
as $$
declare
  v_actor uuid := auth.uid();
  v_course_id uuid;
  v_course_title text;
  v_quiz_title text;
begin
  if exists (
    select 1 from public.notifications n
    where n.quiz_id = new.course_quiz_id and n.kind = 'general_quiz'
  ) then
    return new;
  end if;

  select cq.course_id, cq.title, c.title
    into v_course_id, v_quiz_title, v_course_title
  from public.course_quizzes cq
  join public.courses c on c.id = cq.course_id
  where cq.id = new.course_quiz_id;
  if v_course_id is null then return new; end if;

  insert into public.notifications (user_id, course_id, quiz_id, audience, kind, title, message)
  select e.user_id, v_course_id, new.course_quiz_id, 'student', 'general_quiz',
    'New course quiz',
    'A new general course quiz "' || v_quiz_title || '" is now available for '
      || v_course_title || '.'
  from public.enrollments e
  where e.course_id = v_course_id and e.user_id is distinct from v_actor;

  return new;
end;
$$;

create or replace function public.notify_new_enrollment()
returns trigger
language plpgsql security definer set search_path = public
as $$
declare
  v_lecturer uuid;
  v_course_title text;
  v_student text;
begin
  select claimed_by into v_lecturer from public.lecturer_slots where course_id = new.course_id;
  if v_lecturer is null or v_lecturer = new.user_id then return new; end if;

  select c.title into v_course_title from public.courses c where c.id = new.course_id;
  select coalesce(nullif(btrim(full_name), ''), 'A student')
    into v_student from public.profiles where id = new.user_id;

  insert into public.notifications (user_id, course_id, audience, kind, title, message)
  values (
    v_lecturer, new.course_id, 'lecturer', 'enrollment', 'New student enrollment',
    coalesce(v_student, 'A student') || ' enrolled in ' || coalesce(v_course_title, 'your course') || '.'
  );

  return new;
end;
$$;

create or replace function public.notify_quiz_completed()
returns trigger
language plpgsql security definer set search_path = public
as $$
declare
  v_course_id uuid;
  v_course_title text;
  v_quiz_label text;
  v_lecturer uuid;
  v_student text;
  v_is_module boolean;
  v_first_completion boolean := false;
  v_score_txt text;
begin
  if old.finished_at is not null or new.finished_at is null then
    return new;
  end if;

  if new.topic_id is not null then
    v_is_module := true;
    select t.course_id, c.title, t.title
      into v_course_id, v_course_title, v_quiz_label
    from public.topics t join public.courses c on c.id = t.course_id
    where t.id = new.topic_id;
  elsif new.course_quiz_id is not null then
    v_is_module := false;
    select cq.course_id, c.title, cq.title
      into v_course_id, v_course_title, v_quiz_label
    from public.course_quizzes cq join public.courses c on c.id = cq.course_id
    where cq.id = new.course_quiz_id;
  else
    return new;
  end if;
  if v_course_id is null then return new; end if;

  select claimed_by into v_lecturer from public.lecturer_slots where course_id = v_course_id;
  if v_lecturer is null or v_lecturer = new.user_id then return new; end if;

  select coalesce(nullif(btrim(full_name), ''), 'A student')
    into v_student from public.profiles where id = new.user_id;
  v_score_txt := coalesce(new.score, 0)::text || '/' || coalesce(new.total, 0)::text;

  if v_is_module then
    select count(*) = 1 into v_first_completion
    from public.quiz_attempts a
    where a.user_id = new.user_id and a.topic_id = new.topic_id and a.finished_at is not null;
  end if;

  if v_is_module and v_first_completion then
    insert into public.notifications (user_id, course_id, topic_id, audience, kind, title, message)
    values (
      v_lecturer, v_course_id, new.topic_id, 'lecturer', 'module_completed',
      'Student completed a module',
      coalesce(v_student, 'A student') || ' completed the module "' || coalesce(v_quiz_label, 'a module')
        || '" (' || v_score_txt || ').'
    );
  elsif v_is_module then
    insert into public.notifications (user_id, course_id, topic_id, audience, kind, title, message)
    values (
      v_lecturer, v_course_id, new.topic_id, 'lecturer', 'quiz_completed',
      'Student completed a quiz',
      coalesce(v_student, 'A student') || ' completed the "' || coalesce(v_quiz_label, 'module')
        || '" module quiz (' || v_score_txt || ').'
    );
  else
    insert into public.notifications (user_id, course_id, quiz_id, audience, kind, title, message)
    values (
      v_lecturer, v_course_id, new.course_quiz_id, 'lecturer', 'quiz_completed',
      'Student completed a quiz',
      coalesce(v_student, 'A student') || ' completed the general course quiz "'
        || coalesce(v_quiz_label, 'a quiz') || '" (' || v_score_txt || ').'
    );
  end if;

  return new;
end;
$$;

create or replace function public.notify_lesson_updated()
returns trigger
language plpgsql security definer set search_path = public
as $$
declare
  v_actor uuid := auth.uid();
  v_course_id uuid;
  v_course_title text;
  v_topic_title text;
  v_what text;
begin
  select t.course_id, t.title, c.title
    into v_course_id, v_topic_title, v_course_title
  from public.topics t join public.courses c on c.id = t.course_id
  where t.id = new.topic_id;
  if v_course_id is null then return new; end if;

  if new.title is distinct from old.title then
    v_what := 'renamed to "' || new.title || '"';
  elsif new.modality is distinct from old.modality then
    v_what := 'changed to a ' || new.modality::text || ' lesson';
  elsif new.media_url is distinct from old.media_url then
    v_what := 'has a new resource';
  else
    v_what := 'was updated';
  end if;

  insert into public.notifications (user_id, course_id, topic_id, audience, kind, title, message)
  select e.user_id, v_course_id, new.topic_id, 'student', 'material_updated',
    'Learning material updated',
    'The lesson "' || old.title || '" in ' || v_topic_title || ' ' || v_what
      || ' — open ' || v_topic_title || ' in ' || v_course_title || ' to view it.'
  from public.enrollments e
  where e.course_id = v_course_id and e.user_id is distinct from v_actor;

  return new;
end;
$$;

create or replace function public.notify_module_updated()
returns trigger
language plpgsql security definer set search_path = public
as $$
declare
  v_actor uuid := auth.uid();
  v_course_title text;
  v_what text;
begin
  select c.title into v_course_title from public.courses c where c.id = new.course_id;
  if v_course_title is null then return new; end if;

  if new.title is distinct from old.title then
    v_what := 'was renamed to "' || new.title || '"';
  else
    v_what := 'details were updated';
  end if;

  insert into public.notifications (user_id, course_id, topic_id, audience, kind, title, message)
  select e.user_id, new.course_id, new.id, 'student', 'module_updated',
    'Module updated',
    'The module "' || old.title || '" ' || v_what || ' in ' || v_course_title || '.'
  from public.enrollments e
  where e.course_id = new.course_id and e.user_id is distinct from v_actor;

  return new;
end;
$$;

create or replace function public.notify_quiz_updated()
returns trigger
language plpgsql security definer set search_path = public
as $$
declare
  v_actor uuid := auth.uid();
  v_topic uuid;
  v_cq uuid;
  v_course_id uuid;
  v_course_title text;
  v_label text;
  v_message text;
begin
  if tg_op = 'DELETE' then
    v_topic := old.topic_id; v_cq := old.course_quiz_id;
  else
    v_topic := new.topic_id; v_cq := new.course_quiz_id;
  end if;

  if tg_op = 'UPDATE'
     and new.prompt is not distinct from old.prompt
     and new.choices is not distinct from old.choices
     and new.correct_index is not distinct from old.correct_index
     and new.explanation is not distinct from old.explanation
     and new.difficulty is not distinct from old.difficulty then
    return null;
  end if;

  if v_topic is not null then
    select t.course_id, c.title, t.title
      into v_course_id, v_course_title, v_label
    from public.topics t join public.courses c on c.id = t.course_id
    where t.id = v_topic;
    v_message := 'The quiz for the module "' || coalesce(v_label, 'a module')
      || '" was updated in ' || coalesce(v_course_title, 'your course') || '.';
  elsif v_cq is not null then
    select cq.course_id, c.title, cq.title
      into v_course_id, v_course_title, v_label
    from public.course_quizzes cq join public.courses c on c.id = cq.course_id
    where cq.id = v_cq;
    v_message := 'The general course quiz "' || coalesce(v_label, 'a quiz')
      || '" was updated in ' || coalesce(v_course_title, 'your course') || '.';
  else
    return null;
  end if;
  if v_course_id is null then return null; end if;

  if exists (
    select 1 from public.notifications n
    where n.kind in ('module_quiz', 'general_quiz', 'quiz_updated')
      and (
        (v_topic is not null and n.topic_id = v_topic)
        or (v_cq is not null and n.quiz_id = v_cq)
      )
      and n.created_at > now() - interval '45 seconds'
  ) then
    return null;
  end if;

  insert into public.notifications (user_id, course_id, topic_id, quiz_id, audience, kind, title, message)
  select e.user_id, v_course_id, v_topic, v_cq, 'student', 'quiz_updated',
    'Quiz updated', v_message
  from public.enrollments e
  where e.course_id = v_course_id and e.user_id is distinct from v_actor;

  return null;
end;
$$;


-- 3.14 AI tutor: the only writer for public.ai_messages ----------------------
-- SECURITY DEFINER so it can insert despite the client having no write grant.
-- Re-verifies the caller owns the conversation (auth.uid()), accepts only the
-- four fields a turn needs, and always writes one user + one assistant row.
create or replace function public.append_ai_turn(
  _conversation_id   uuid,
  _user_content      text,
  _assistant_content text,
  _mode              text
)
returns void
language plpgsql security definer set search_path = public
as $$
declare
  v_owner uuid;
  v_mode  text := coalesce(nullif(trim(_mode), ''), 'ask');
begin
  if auth.uid() is null then
    raise exception 'forbidden';
  end if;
  if _conversation_id is null
     or coalesce(trim(_user_content), '') = ''
     or coalesce(trim(_assistant_content), '') = '' then
    raise exception 'append_ai_turn: missing required content';
  end if;
  if v_mode not in ('general', 'ask', 'explain', 'summarize', 'test', 'guide', 'recommend') then
    raise exception 'append_ai_turn: invalid mode %', v_mode;
  end if;

  select user_id into v_owner
  from public.ai_conversations where id = _conversation_id for update;
  if v_owner is null or v_owner <> auth.uid() then
    raise exception 'forbidden';
  end if;

  insert into public.ai_messages (conversation_id, role, content, mode) values
    (_conversation_id, 'user',      _user_content,      v_mode),
    (_conversation_id, 'assistant', _assistant_content, v_mode);

  update public.ai_conversations
     set last_message_at = now(),
         title = coalesce(title, left(_user_content, 80))
   where id = _conversation_id;
end;
$$;

-- Clear Conversation: delete ALL of the caller's OWN AI conversations for one
-- course (messages cascade). Scoped by auth.uid() + the given course id, so a
-- student can only clear their own and only for that one course.
create or replace function public.clear_course_conversations(_course_id uuid)
returns integer
language plpgsql security definer set search_path = public
as $$
declare
  v_deleted integer;
begin
  if auth.uid() is null then
    raise exception 'forbidden';
  end if;
  if _course_id is null then
    raise exception 'clear_course_conversations: course id required';
  end if;
  delete from public.ai_conversations
   where user_id = auth.uid() and course_id = _course_id;
  get diagnostics v_deleted = row_count;
  return v_deleted;
end;
$$;


-- 3.15 scheduled: General Course Quiz availability / deadline notifications ----
-- Idempotent sweep run by pg_cron every 15 minutes (scheduled in section 9).
-- Emits "available" / "due soon" / "closed" rows for students + the lecturer
-- into public.notifications. Every row carries a deterministic event_key; the
-- unique index (user_id, event_key) + ON CONFLICT DO NOTHING makes repeat runs
-- no-ops. Recipients come only from enrollments + lecturer_slots.
create or replace function public.sweep_general_quiz_schedule()
returns int
language plpgsql
security definer
set search_path = public
as $$
declare
  v_total int := 0;
  v_n int;
begin
  -- STUDENT: quiz now available (only for a quiz whose available_from was set in
  -- the future and has now arrived; a quiz with no available_from is announced
  -- by notify_new_general_quiz on publish).
  insert into public.notifications
    (user_id, course_id, quiz_id, audience, kind, title, message, event_key)
  select
    e.user_id, cq.course_id, cq.id, 'student', 'general_quiz_available',
    'General Course Quiz available',
    'The General Course Quiz "' || cq.title || '" for ' || c.title
      || ' is now available'
      || case when cq.deadline is null then '.'
              else '. It is due '
                   || to_char(cq.deadline at time zone 'UTC',
                              'FMMon FMDD, YYYY "at" HH12:MI AM') || ' UTC.' end,
    'gcq_avail:' || cq.id::text || ':' || extract(epoch from cq.available_from)::bigint::text
  from public.course_quizzes cq
  join public.courses c on c.id = cq.course_id
  join public.enrollments e on e.course_id = cq.course_id
  where cq.available_from is not null and now() >= cq.available_from
    and exists (select 1 from public.questions q where q.course_quiz_id = cq.id)
  on conflict (user_id, event_key) do nothing;
  get diagnostics v_n = row_count; v_total := v_total + v_n;

  -- LECTURER: quiz now active.
  insert into public.notifications
    (user_id, course_id, quiz_id, audience, kind, title, message, event_key)
  select
    ls.claimed_by, cq.course_id, cq.id, 'lecturer', 'general_quiz_active',
    'General Course Quiz is now active',
    'The General Course Quiz "' || cq.title || '" for ' || c.title
      || ' is now available to students.',
    'gcq_active:' || cq.id::text || ':' || extract(epoch from cq.available_from)::bigint::text
  from public.course_quizzes cq
  join public.courses c on c.id = cq.course_id
  join public.lecturer_slots ls on ls.course_id = cq.course_id and ls.claimed_by is not null
  where cq.available_from is not null and now() >= cq.available_from
    and exists (select 1 from public.questions q where q.course_quiz_id = cq.id)
  on conflict (user_id, event_key) do nothing;
  get diagnostics v_n = row_count; v_total := v_total + v_n;

  -- STUDENT: deadline within 24h, not yet submitted.
  insert into public.notifications
    (user_id, course_id, quiz_id, audience, kind, title, message, event_key)
  select
    e.user_id, cq.course_id, cq.id, 'student', 'general_quiz_due_soon',
    'General Course Quiz due soon',
    'Your General Course Quiz "' || cq.title || '" for ' || c.title
      || ' is due ' || to_char(cq.deadline at time zone 'UTC',
                               'FMMon FMDD, YYYY "at" HH12:MI AM') || ' UTC.',
    'gcq_soon:' || cq.id::text || ':' || extract(epoch from cq.deadline)::bigint::text
  from public.course_quizzes cq
  join public.courses c on c.id = cq.course_id
  join public.enrollments e on e.course_id = cq.course_id
  where cq.deadline is not null
    and now() >= cq.deadline - interval '24 hours' and now() < cq.deadline
    and (cq.available_from is null or now() >= cq.available_from)
    and exists (select 1 from public.questions q where q.course_quiz_id = cq.id)
    and not exists (
      select 1 from public.quiz_attempts a
      where a.course_quiz_id = cq.id and a.user_id = e.user_id and a.finished_at is not null
    )
  on conflict (user_id, event_key) do nothing;
  get diagnostics v_n = row_count; v_total := v_total + v_n;

  -- STUDENT: deadline passed, never submitted.
  insert into public.notifications
    (user_id, course_id, quiz_id, audience, kind, title, message, event_key)
  select
    e.user_id, cq.course_id, cq.id, 'student', 'general_quiz_closed',
    'General Course Quiz closed',
    'The General Course Quiz "' || cq.title || '" for ' || c.title
      || ' closed on ' || to_char(cq.deadline at time zone 'UTC',
                                  'FMMon FMDD, YYYY "at" HH12:MI AM') || ' UTC.',
    'gcq_closed:' || cq.id::text || ':' || extract(epoch from cq.deadline)::bigint::text
  from public.course_quizzes cq
  join public.courses c on c.id = cq.course_id
  join public.enrollments e on e.course_id = cq.course_id
  where cq.deadline is not null and now() >= cq.deadline
    and exists (select 1 from public.questions q where q.course_quiz_id = cq.id)
    and not exists (
      select 1 from public.quiz_attempts a
      where a.course_quiz_id = cq.id and a.user_id = e.user_id and a.finished_at is not null
    )
  on conflict (user_id, event_key) do nothing;
  get diagnostics v_n = row_count; v_total := v_total + v_n;

  -- LECTURER: deadline reached, with the real submission summary.
  insert into public.notifications
    (user_id, course_id, quiz_id, audience, kind, title, message, event_key)
  select
    ls.claimed_by, cq.course_id, cq.id, 'lecturer', 'general_quiz_deadline',
    'General Course Quiz deadline reached',
    'The General Course Quiz "' || cq.title || '" for ' || c.title || ' has closed. '
      || (select count(distinct a.user_id) from public.quiz_attempts a
            where a.course_quiz_id = cq.id and a.finished_at is not null)::text
      || ' of '
      || (select count(*) from public.enrollments e2 where e2.course_id = cq.course_id)::text
      || ' enrolled students submitted.',
    'gcq_dl:' || cq.id::text || ':' || extract(epoch from cq.deadline)::bigint::text
  from public.course_quizzes cq
  join public.courses c on c.id = cq.course_id
  join public.lecturer_slots ls on ls.course_id = cq.course_id and ls.claimed_by is not null
  where cq.deadline is not null and now() >= cq.deadline
    and exists (select 1 from public.questions q where q.course_quiz_id = cq.id)
  on conflict (user_id, event_key) do nothing;
  get diagnostics v_n = row_count; v_total := v_total + v_n;

  return v_total;
end;
$$;


-- ============================================================================
-- 4. TRIGGERS
-- ============================================================================

-- auth: provision a profile + student role on every new user
drop trigger if exists on_auth_user_created on auth.users;
create trigger on_auth_user_created
  after insert on auth.users
  for each row execute function public.handle_new_user();

-- quiz_attempts: BEFORE INSERT (guard first, then stamp the expiry)
drop trigger if exists trg_enforce_course_quiz_attempt on public.quiz_attempts;
create trigger trg_enforce_course_quiz_attempt
  before insert on public.quiz_attempts
  for each row execute function public.enforce_course_quiz_attempt();

drop trigger if exists trg_stamp_quiz_attempt_expiry on public.quiz_attempts;
create trigger trg_stamp_quiz_attempt_expiry
  before insert on public.quiz_attempts
  for each row execute function public.stamp_quiz_attempt_expiry();

-- quiz_attempts: AFTER UPDATE — lecturer "student completed a quiz/module"
drop trigger if exists trg_notify_quiz_completed on public.quiz_attempts;
create trigger trg_notify_quiz_completed
  after update on public.quiz_attempts
  for each row execute function public.notify_quiz_completed();

-- questions: deferred constraint triggers (checked at COMMIT)
drop trigger if exists trg_topic_has_questions on public.questions;
create constraint trigger trg_topic_has_questions
  after delete on public.questions
  deferrable initially deferred
  for each row execute function public.assert_topic_has_questions();

drop trigger if exists trg_course_quiz_has_questions on public.questions;
create constraint trigger trg_course_quiz_has_questions
  after delete on public.questions
  deferrable initially deferred
  for each row execute function public.assert_course_quiz_has_questions();

-- questions: student "new general course quiz" (first question inserted)
drop trigger if exists trg_notify_new_general_quiz on public.questions;
create trigger trg_notify_new_general_quiz
  after insert on public.questions
  for each row
  when (new.course_quiz_id is not null)
  execute function public.notify_new_general_quiz();

-- questions: student "quiz updated"
drop trigger if exists trg_notify_quiz_updated on public.questions;
create trigger trg_notify_quiz_updated
  after insert or update or delete on public.questions
  for each row execute function public.notify_quiz_updated();

-- lessons: student "new / updated learning material"
drop trigger if exists trg_notify_new_lesson on public.lessons;
create trigger trg_notify_new_lesson
  after insert on public.lessons
  for each row execute function public.notify_new_lesson();

drop trigger if exists trg_notify_lesson_updated on public.lessons;
create trigger trg_notify_lesson_updated
  after update on public.lessons
  for each row
  when (
    new.title    is distinct from old.title
    or new.body_md   is distinct from old.body_md
    or new.modality  is distinct from old.modality
    or new.media_url is distinct from old.media_url
  )
  execute function public.notify_lesson_updated();

-- topics: student "new / updated module"
drop trigger if exists trg_notify_new_module on public.topics;
create trigger trg_notify_new_module
  after insert on public.topics
  for each row execute function public.notify_new_module();

drop trigger if exists trg_notify_module_updated on public.topics;
create trigger trg_notify_module_updated
  after update on public.topics
  for each row
  when (
    new.title is distinct from old.title
    or new.summary is distinct from old.summary
  )
  execute function public.notify_module_updated();

-- enrollments: lecturer "new student enrolled"
drop trigger if exists trg_notify_new_enrollment on public.enrollments;
create trigger trg_notify_new_enrollment
  after insert on public.enrollments
  for each row execute function public.notify_new_enrollment();


-- ============================================================================
-- 5. ROW LEVEL SECURITY  +  POLICIES
-- ============================================================================

alter table public.profiles              enable row level security;
alter table public.user_roles            enable row level security;
alter table public.courses               enable row level security;
alter table public.topics                enable row level security;
alter table public.lessons               enable row level security;
alter table public.course_quizzes        enable row level security;
alter table public.questions             enable row level security;
alter table public.quiz_attempts         enable row level security;
alter table public.attempt_answers       enable row level security;
alter table public.progress              enable row level security;
alter table public.enrollments           enable row level security;
alter table public.study_sessions        enable row level security;
alter table public.lecturer_slots        enable row level security;
alter table public.notifications         enable row level security;
alter table public.study_paths           enable row level security;
alter table public.learning_preferences  enable row level security;
alter table public.ai_conversations      enable row level security;
alter table public.ai_messages           enable row level security;
alter table public.vark_profiles         enable row level security;

-- profiles: read / write only your own row
create policy "profiles_select_own" on public.profiles for select to authenticated using (auth.uid() = id);
create policy "profiles_update_own" on public.profiles for update to authenticated using (auth.uid() = id);
create policy "profiles_insert_own" on public.profiles for insert to authenticated with check (auth.uid() = id);

-- user_roles: read only your own; writes are SECURITY DEFINER only
create policy "user_roles_select_own" on public.user_roles for select to authenticated using (auth.uid() = user_id);

-- courses / topics / lessons / course_quizzes: public read; lecturer scoped write
create policy "courses_public_read" on public.courses for select to anon, authenticated using (true);

create policy "topics_public_read" on public.topics for select to anon, authenticated using (true);
create policy "topics_lecturer_write" on public.topics
  for all to authenticated
  using (course_id = public.current_lecturer_course())
  with check (course_id = public.current_lecturer_course());

create policy "lessons_public_read" on public.lessons for select to anon, authenticated using (true);
create policy "lessons_lecturer_write" on public.lessons
  for all to authenticated
  using (topic_id in (select t.id from public.topics t where t.course_id = public.current_lecturer_course()))
  with check (topic_id in (select t.id from public.topics t where t.course_id = public.current_lecturer_course()));

create policy "course_quizzes_public_read" on public.course_quizzes
  for select to anon, authenticated using (true);
create policy "course_quizzes_lecturer_write" on public.course_quizzes
  for all to authenticated
  using (course_id = public.current_lecturer_course())
  with check (course_id = public.current_lecturer_course());

-- questions: any authenticated user may read; lecturer scoped write (module OR their course quiz)
create policy "Authenticated can read questions" on public.questions
  for select to authenticated using (true);
create policy "questions_lecturer_write" on public.questions
  for all to authenticated
  using (
    (topic_id in (select t.id from public.topics t where t.course_id = public.current_lecturer_course()))
    or
    (course_quiz_id in (select cq.id from public.course_quizzes cq where cq.course_id = public.current_lecturer_course()))
  )
  with check (
    (topic_id in (select t.id from public.topics t where t.course_id = public.current_lecturer_course()))
    or
    (course_quiz_id in (select cq.id from public.course_quizzes cq where cq.course_id = public.current_lecturer_course()))
  );

-- quiz_attempts: own rows (select / insert / update / delete)
create policy "attempts_select_own" on public.quiz_attempts for select to authenticated using (auth.uid() = user_id);
create policy "attempts_insert_own" on public.quiz_attempts for insert to authenticated with check (auth.uid() = user_id);
create policy "attempts_update_own" on public.quiz_attempts for update to authenticated using (auth.uid() = user_id);
create policy "attempts_delete_own" on public.quiz_attempts for delete to authenticated using (auth.uid() = user_id);

-- attempt_answers: rows whose parent attempt is yours. SELECT is withheld until
-- the attempt is FINISHED so a student can't read is_correct on the answers they
-- saved mid-quiz (Quiz Recovery). Resume reads selected indices via the
-- SECURITY DEFINER get_attempt_answers() instead.
create policy "answers_select_own" on public.attempt_answers for select to authenticated
  using (exists (
    select 1 from public.quiz_attempts a
    where a.id = attempt_id and a.user_id = auth.uid() and a.finished_at is not null
  ));
create policy "answers_insert_own" on public.attempt_answers for insert to authenticated
  with check (exists (select 1 from public.quiz_attempts a where a.id = attempt_id and a.user_id = auth.uid()));
create policy "answers_delete_own" on public.attempt_answers for delete to authenticated
  using (exists (select 1 from public.quiz_attempts a where a.id = attempt_id and a.user_id = auth.uid()));

-- progress: own rows
create policy "progress_select_own" on public.progress for select to authenticated using (auth.uid() = user_id);
create policy "progress_insert_own" on public.progress for insert to authenticated with check (auth.uid() = user_id);
create policy "progress_update_own" on public.progress for update to authenticated using (auth.uid() = user_id);
create policy "progress_delete_own" on public.progress for delete to authenticated using (auth.uid() = user_id);

-- enrollments: own rows
create policy "enrollments_select_own" on public.enrollments for select to authenticated using (auth.uid() = user_id);
create policy "enrollments_insert_own" on public.enrollments for insert to authenticated with check (auth.uid() = user_id);
create policy "enrollments_delete_own" on public.enrollments for delete to authenticated using (auth.uid() = user_id);

-- study_sessions: own rows
create policy "study_sessions_select_own" on public.study_sessions for select to authenticated using (auth.uid() = user_id);
create policy "study_sessions_insert_own" on public.study_sessions for insert to authenticated with check (auth.uid() = user_id);
create policy "study_sessions_update_own" on public.study_sessions for update to authenticated using (auth.uid() = user_id);
create policy "study_sessions_delete_own" on public.study_sessions for delete to authenticated using (auth.uid() = user_id);

-- lecturer_slots: read only your own claimed slot; no client writes
create policy "lecturer_slots_select_own" on public.lecturer_slots
  for select to authenticated using (claimed_by = auth.uid());
revoke insert, update, delete on public.lecturer_slots from anon, authenticated;

-- notifications: own rows for select / update / delete; inserts are trigger-only
create policy "notifications_select_own" on public.notifications for select to authenticated using (auth.uid() = user_id);
create policy "notifications_update_own" on public.notifications for update to authenticated using (auth.uid() = user_id);
create policy "notifications_delete_own" on public.notifications for delete to authenticated using (auth.uid() = user_id);

-- study_paths: read your own; writes are SECURITY DEFINER only
create policy "study_paths_select_own" on public.study_paths
  for select to authenticated using (auth.uid() = user_id);

-- learning_preferences: own row only
create policy "learning_preferences_select_own" on public.learning_preferences
  for select to authenticated using (auth.uid() = user_id);
create policy "learning_preferences_insert_own" on public.learning_preferences
  for insert to authenticated with check (auth.uid() = user_id);
create policy "learning_preferences_update_own" on public.learning_preferences
  for update to authenticated using (auth.uid() = user_id) with check (auth.uid() = user_id);
create policy "learning_preferences_delete_own" on public.learning_preferences
  for delete to authenticated using (auth.uid() = user_id);

-- ai_conversations: a student owns and manages their own
create policy "ai_conversations_select_own" on public.ai_conversations
  for select to authenticated using (user_id = auth.uid());
create policy "ai_conversations_insert_own" on public.ai_conversations
  for insert to authenticated with check (user_id = auth.uid());
create policy "ai_conversations_update_own" on public.ai_conversations
  for update to authenticated using (user_id = auth.uid()) with check (user_id = auth.uid());
create policy "ai_conversations_delete_own" on public.ai_conversations
  for delete to authenticated using (user_id = auth.uid());

-- ai_messages: browser gets SELECT only. No insert/update/delete policy AND the
-- grants are revoked below, so a client cannot forge or alter AI history. The
-- only writer is the SECURITY DEFINER append_ai_turn() (section 3).
create policy "ai_messages_select_own" on public.ai_messages for select to authenticated
  using (exists (select 1 from public.ai_conversations c
                 where c.id = conversation_id and c.user_id = auth.uid()));
revoke insert, update, delete on public.ai_messages from anon, authenticated;

-- vark_profiles: own row only. No lecturer policy — never lecturer-visible,
-- same as learning_preferences.
create policy "vark_profiles_select_own" on public.vark_profiles
  for select to authenticated using (auth.uid() = user_id);
create policy "vark_profiles_insert_own" on public.vark_profiles
  for insert to authenticated with check (auth.uid() = user_id);
create policy "vark_profiles_update_own" on public.vark_profiles
  for update to authenticated using (auth.uid() = user_id) with check (auth.uid() = user_id);
create policy "vark_profiles_delete_own" on public.vark_profiles
  for delete to authenticated using (auth.uid() = user_id);


-- ============================================================================
-- 6. GRANTS
-- ============================================================================

-- 6.1 Schema + table access. RLS above is the real access control; these grants
--     only let PostgREST attempt the query. (Matches Supabase's default model.)
grant usage on schema public to anon, authenticated, service_role;
grant all on all tables      in schema public to anon, authenticated, service_role;
grant all on all sequences   in schema public to anon, authenticated, service_role;
alter default privileges in schema public grant all on tables    to anon, authenticated, service_role;
alter default privileges in schema public grant all on sequences to anon, authenticated, service_role;

-- Explicit (matches migration 20260611211725).
grant select on public.questions to authenticated;

-- 6.2 Function EXECUTE. Supabase auto-grants EXECUTE on new functions to
--     anon+authenticated via default privileges, so every function is first
--     REVOKEd and then GRANTed exactly where it belongs.

-- internal / trigger-only functions: callable only by their SECURITY DEFINER owner
revoke execute on function public.has_role(uuid, public.app_role)      from public, anon, authenticated;
revoke execute on function public.handle_new_user()                    from public, anon, authenticated;
revoke execute on function public.enforce_course_quiz_attempt()        from public, anon;
revoke execute on function public.stamp_quiz_attempt_expiry()          from public, anon;
revoke execute on function public.assert_topic_has_questions()         from public, anon;
revoke execute on function public.assert_course_quiz_has_questions()   from public, anon;
revoke execute on function public.notify_new_lesson()                  from public, anon, authenticated;
revoke execute on function public.notify_new_module()                  from public, anon, authenticated;
revoke execute on function public.notify_new_general_quiz()            from public, anon, authenticated;
revoke execute on function public.notify_new_enrollment()              from public, anon, authenticated;
revoke execute on function public.notify_quiz_completed()              from public, anon, authenticated;
revoke execute on function public.notify_lesson_updated()              from public, anon, authenticated;
revoke execute on function public.notify_module_updated()              from public, anon, authenticated;
revoke execute on function public.notify_quiz_updated()                from public, anon, authenticated;

-- callable RPCs
revoke execute on function public.current_lecturer_course()                                        from public;
grant  execute on function public.current_lecturer_course()                                        to authenticated;

revoke execute on function public.lecturer_id_available(text)                                      from public;
grant  execute on function public.lecturer_id_available(text)                                      to anon, authenticated;

revoke execute on function public.claim_lecturer_slot(text)                                        from public, anon;
grant  execute on function public.claim_lecturer_slot(text)                                        to authenticated;

revoke execute on function public.get_quiz_questions(uuid, int)                                    from public, anon;
grant  execute on function public.get_quiz_questions(uuid, int)                                    to authenticated;

revoke execute on function public.get_course_quiz_questions(uuid, int)                             from public, anon;
grant  execute on function public.get_course_quiz_questions(uuid, int)                             to authenticated;

revoke execute on function public.grade_quiz(uuid, jsonb, boolean)                                 from public, anon;
grant  execute on function public.grade_quiz(uuid, jsonb, boolean)                                 to authenticated;

revoke execute on function public.save_quiz_answer(uuid, uuid, int)                                from public, anon;
grant  execute on function public.save_quiz_answer(uuid, uuid, int)                                to authenticated;

revoke execute on function public.get_attempt_answers(uuid)                                        from public, anon;
grant  execute on function public.get_attempt_answers(uuid)                                        to authenticated;

revoke execute on function public.finalize_expired_quiz_attempts()                                 from public, anon;
grant  execute on function public.finalize_expired_quiz_attempts()                                 to authenticated;

revoke execute on function public.publish_teacher_note(uuid, text, text, text)                     from public, anon;
grant  execute on function public.publish_teacher_note(uuid, text, text, text)                     to authenticated;

revoke execute on function public.publish_teacher_quiz(uuid, text, text, jsonb)                    from public, anon;
grant  execute on function public.publish_teacher_quiz(uuid, text, text, jsonb)                    to authenticated;

revoke execute on function public.create_module_with_quiz(text, text, jsonb, jsonb, int)           from public, anon;
grant  execute on function public.create_module_with_quiz(text, text, jsonb, jsonb, int)           to authenticated;

revoke execute on function public.replace_topic_quiz(uuid, jsonb)                                  from public, anon;
grant  execute on function public.replace_topic_quiz(uuid, jsonb)                                  to authenticated;

