-- ============================================================================
-- 7. STORAGE  (buckets + storage.objects policies)
--    storage.objects already has RLS enabled in every Supabase project.
-- ============================================================================

-- 7.1 Buckets
--   avatars         — private; profile pictures served via signed URLs
--   course-materials — public read; lecturer-uploaded lesson video/audio/PDF
insert into storage.buckets (id, name, public)
values ('avatars', 'avatars', false)
on conflict (id) do nothing;

insert into storage.buckets (id, name, public, file_size_limit, allowed_mime_types)
values (
  'course-materials', 'course-materials', true, 52428800,
  array[
    'video/mp4', 'video/webm', 'video/ogg', 'video/quicktime',
    'audio/mpeg', 'audio/mp3', 'audio/wav', 'audio/x-wav', 'audio/ogg',
    'audio/aac', 'audio/mp4', 'audio/x-m4a',
    'application/pdf'
  ]
)
on conflict (id) do update
  set public = excluded.public,
      file_size_limit = excluded.file_size_limit,
      allowed_mime_types = excluded.allowed_mime_types;

-- 7.2 avatars policies: a user owns the folder named after their auth id
--     path shape:  avatars/{auth.uid}/{file}
drop policy if exists "Avatar read own"   on storage.objects;
drop policy if exists "Avatar insert own" on storage.objects;
drop policy if exists "Avatar update own" on storage.objects;
drop policy if exists "Avatar delete own" on storage.objects;

create policy "Avatar read own" on storage.objects for select to authenticated
  using (bucket_id = 'avatars' and auth.uid()::text = (storage.foldername(name))[1]);
create policy "Avatar insert own" on storage.objects for insert to authenticated
  with check (bucket_id = 'avatars' and auth.uid()::text = (storage.foldername(name))[1]);
create policy "Avatar update own" on storage.objects for update to authenticated
  using (bucket_id = 'avatars' and auth.uid()::text = (storage.foldername(name))[1]);
create policy "Avatar delete own" on storage.objects for delete to authenticated
  using (bucket_id = 'avatars' and auth.uid()::text = (storage.foldername(name))[1]);

-- 7.3 course-materials policies: public read; only the assigned lecturer may
--     write under their own course folder.
--     path shape:  course-materials/{course_id}/{topic_id}/{uuid}.{ext}
drop policy if exists "course_materials_public_read"       on storage.objects;
drop policy if exists "course_materials_lecturer_insert"   on storage.objects;
drop policy if exists "course_materials_lecturer_update"   on storage.objects;
drop policy if exists "course_materials_lecturer_delete"   on storage.objects;

create policy "course_materials_public_read" on storage.objects
  for select to anon, authenticated
  using (bucket_id = 'course-materials');

create policy "course_materials_lecturer_insert" on storage.objects
  for insert to authenticated
  with check (
    bucket_id = 'course-materials'
    and (storage.foldername(name))[1] = public.current_lecturer_course()::text
  );

create policy "course_materials_lecturer_update" on storage.objects
  for update to authenticated
  using (
    bucket_id = 'course-materials'
    and (storage.foldername(name))[1] = public.current_lecturer_course()::text
  )
  with check (
    bucket_id = 'course-materials'
    and (storage.foldername(name))[1] = public.current_lecturer_course()::text
  );

create policy "course_materials_lecturer_delete" on storage.objects
  for delete to authenticated
  using (
    bucket_id = 'course-materials'
    and (storage.foldername(name))[1] = public.current_lecturer_course()::text
  );


-- ============================================================================
-- 8. SYSTEM CONFIGURATION  —  the 5 fixed Lecturer IDs
--    Each Lecturer ID is permanently bound to ONE course. This depends on the
--    matching courses existing first, so run it AFTER you have seeded your
--    course catalogue with these slugs. It is idempotent and non-destructive:
--    if a course slug is missing it simply inserts fewer rows; re-run it later.
--    (Migration 20260830120000 seeded these exact IDs -> slugs.)
-- ============================================================================
insert into public.lecturer_slots (lecturer_id, course_id)
select v.lecturer_id, c.id
from (values
  ('LECT-001', 'dsa'),
  ('LECT-002', 'dbms'),
  ('LECT-003', 'networks'),
  ('LECT-004', 'se'),
  ('LECT-005', 'ai')
) as v(lecturer_id, slug)
join public.courses c on c.slug = v.slug
on conflict (lecturer_id) do nothing;


-- ============================================================================
-- 9. SCHEDULED JOBS  (pg_cron)
--    Runs public.sweep_general_quiz_schedule() every 15 minutes to emit the
--    General Course Quiz availability / due-soon / closed notifications. The
--    sweep is idempotent, so the cadence only bounds delivery latency.
--    Best-effort: if the migration role cannot enable pg_cron, this only raises
--    a NOTICE — enable pg_cron (Dashboard -> Database -> Extensions) and run the
--    cron.schedule() call below by hand, once.
-- ============================================================================
do $$
begin
  execute 'create extension if not exists pg_cron';
  begin
    perform cron.unschedule('gcq-schedule-sweep');
  exception when others then null;
  end;
  perform cron.schedule(
    'gcq-schedule-sweep', '*/15 * * * *',
    'select public.sweep_general_quiz_schedule();'
  );
  raise notice 'pg_cron: scheduled gcq-schedule-sweep (every 15 minutes).';
exception when others then
  raise notice 'pg_cron not scheduled automatically (%). Enable pg_cron, then run: select cron.schedule(''gcq-schedule-sweep'', ''*/15 * * * *'', ''select public.sweep_general_quiz_schedule();'');', sqlerrm;
end $$;


